34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
41	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
42	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
44	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
45	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
46	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
47	import org.springframework.samples.petclinic.rest.api.OwnersApi;
48	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
49	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
50	import org.springframework.samples.petclinic.rest.dto.PetDto;
51	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
52	import org.springframework.samples.petclinic.rest.dto.VisitDto;
53	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
54	import org.springframework.samples.petclinic.service.ClinicService;
55	import org.springframework.security.access.prepost.PreAuthorize;
56	import org.springframework.web.bind.annotation.CrossOrigin;
57	import org.springframework.web.bind.annotation.RequestMapping;
58	import org.springframework.web.bind.annotation.RestController;
59	import org.springframework.web.util.UriComponentsBuilder;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
74	     * the {@code customerCode} and the {@code registrationDate} is emitted to this named logger.
75	     */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper) {
90	        this.clinicService = clinicService;
91	        this.ownerMapper = ownerMapper;
92	        this.petMapper = petMapper;
93	        this.visitMapper = visitMapper;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    /**
122	     * Rejects an owner payload that is missing or blank in any of the required fields
123	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
124	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
125	     * value as present; this guard closes that gap so a blank in any required field is
126	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
127	     * the name of each offending field.
128	     */
129	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
130	        List<String> missing = new ArrayList<>();
131	        if (isBlank(ownerFieldsDto.getFirstName())) {
132	            missing.add("firstName");
133	        }
134	        if (isBlank(ownerFieldsDto.getLastName())) {
135	            missing.add("lastName");
136	        }
137	        if (isBlank(normalizedAddress)) {
138	            missing.add("address");
139	        }
140	        if (isBlank(ownerFieldsDto.getCity())) {
141	            missing.add("city");
142	        }
143	        if (isBlank(ownerFieldsDto.getTelephone())) {
144	            missing.add("telephone");
145	        }
146	        if (!missing.isEmpty()) {
147	            throw new MissingOwnerFieldsException(missing);
148	        }
149	    }
150	
151	    private static boolean isBlank(String value) {
152	        return value == null || value.isBlank();
153	    }
154	
155	    /**
156	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
157	     */
158	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
159	
160	    /**
161	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
162	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
163	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
164	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
165	     * stored as '+61412345678'. A value that cannot form a valid E.164 number is rejected via
166	     * {@link InvalidTelephoneException}, which the exception handler translates to a 400.
167	     */
168	    private static String normalizeTelephone(String telephone) {
169	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
170	        String e164;
171	        if (cleaned.startsWith("+")) {
172	            e164 = cleaned;
173	        } else {
174	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
175	            e164 = "+61" + national;
176	        }
177	        if (!E164_PATTERN.matcher(e164).matches()) {
178	            throw new InvalidTelephoneException(telephone);
179	        }
180	        return e164;
181	    }
182	
183	    /**
184	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
185	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
186	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
187	     */
188	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
189	
190	    /**
191	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
192	     * optional). When present it must be a syntactically valid address; a valid value is
193	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
194	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
195	     */
196	    private static String normalizeEmail(String email) {
197	        if (email == null) {
198	            return null;
199	        }
200	        if (!EMAIL_PATTERN.matcher(email).matches()) {
201	            throw new InvalidEmailException(email);
202	        }
203	        return email.toLowerCase(Locale.ROOT);
204	    }
205	
206	    /**
207	     * Rejects a create whose normalized telephone is already used by another owner. Each
208	     * existing owner's stored telephone is reduced to its E.164 form the same way {@code
209	     * normalizeTelephone} does, so the comparison is on the canonical E.164 value regardless of
210	     * the format each was originally entered in. An existing value that cannot form a valid E.164
211	     * number is skipped rather than colliding. A match is reported via
212	     * {@link DuplicateTelephoneException}, which the exception handler translates to a 409.
213	     */
214	    private void rejectDuplicateTelephone(String normalizedTelephone) {
215	        for (Owner existing : this.clinicService.findAllOwners()) {
216	            String existingE164;
217	            try {
218	                existingE164 = normalizeTelephone(existing.getTelephone());
219	            } catch (InvalidTelephoneException ex) {
220	                continue;
221	            }
222	            if (normalizedTelephone.equals(existingE164)) {
223	                throw new DuplicateTelephoneException(normalizedTelephone);
224	            }
225	        }
226	    }
227	
228	    /**
229	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
230	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
231	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
232	     * spacing do not defeat the duplicate-household check.
233	     */
234	    private static String collapse(String value) {
235	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
236	    }
237	
238	    /**
239	     * Normalizes an owner's address into a canonical form applied on every create: leading and
240	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
241	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
242	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
243	     * and returned, and is the form every address comparison (duplicate-household detection and the
244	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
245	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
246	     * so normalizing an already-normalized address is a no-op.
247	     */
248	    private static String normalizeAddress(String address) {
249	        if (address == null) {
250	            return "";
251	        }
252	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
253	        if (collapsed.isEmpty()) {
254	            return "";
255	        }
256	        String[] tokens = collapsed.split(" ");
257	        StringBuilder sb = new StringBuilder(collapsed.length());
258	        for (int i = 0; i < tokens.length; i++) {
259	            String token = tokens[i];
260	            switch (token) {
261	                case "ST" -> token = "STREET";
262	                case "RD" -> token = "ROAD";
263	                case "AVE" -> token = "AVENUE";
264	                default -> {
265	                }
266	            }
267	            if (i > 0) {
268	                sb.append(' ');
269	            }
270	            sb.append(token);
271	        }
272	        return sb.toString();
273	    }
274	
275	    /**
276	     * Rejects a create that would place a second owner in the same household as an existing one -
277	     * i.e. another owner already has the same {@code lastName} and the same {@code address},
278	     * compared case-insensitively with collapsed whitespace. The caller can opt in to sharing a
279	     * household by setting {@code sharesHousehold} true, in which case this check is skipped. A
280	     * match is reported via {@link DuplicateHouseholdException}, which the exception handler
281	     * translates to a 409.
282	     */
283	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
284	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
285	            return;
286	        }
287	        String lastName = collapse(ownerFieldsDto.getLastName());
288	        for (Owner existing : this.clinicService.findAllOwners()) {
289	            if (lastName.equals(collapse(existing.getLastName()))
290	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
291	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
292	            }
293	        }
294	    }
295	
296	    /**
297	     * Builds the {@code customerCode} for a newly created owner, formatted
298	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first three letters of
299	     * {@code city}, {@code LAST3} the upper-cased first three letters of {@code lastName}, and
300	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of
301	     * owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
302	     */
303	    private String nextCustomerCode(String city, String lastName) {
304	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
305	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
306	        int sequence = 1;
307	        for (Owner existing : this.clinicService.findAllOwners()) {
308	            if (city.equalsIgnoreCase(existing.getCity())) {
309	                sequence++;
310	            }
311	        }
312	        return String.format("%s-%s-%04d", city3, last3, sequence);
313	    }
314	
315	    /**
316	     * Builds the {@code membershipNumber} for a newly created owner, formatted
317	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
318	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
319	     */
320	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
321	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
322	    }
323	
324	    /**
325	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
326	     * {@code address} - the same pair used to detect a shared household. Because it is a pure
327	     * function of that pair (upper-case hex of SHA-256 over the two collapsed values), every owner
328	     * in the same household - whether created first or joining later via {@code sharesHousehold} -
329	     * receives the identical, non-blank identifier without needing to read any other owner's value.
330	     */
331	    private static String householdIdFor(String lastName, String address) {
332	        String key = collapse(lastName) + "\n" + normalizeAddress(address);
333	        try {
334	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
335	            StringBuilder sb = new StringBuilder(32);
336	            for (int i = 0; i < 8; i++) {
337	                sb.append(String.format("%02X", digest[i]));
338	            }
339	            return sb.toString();
340	        } catch (NoSuchAlgorithmException ex) {
341	            throw new IllegalStateException("SHA-256 not available", ex);
342	        }
343	    }
344	
345	    /**
346	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
347	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
348	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
349	     */
350	    private int countNamesakes(String firstName, String lastName) {
351	        int count = 0;
352	        for (Owner existing : this.clinicService.findAllOwners()) {
353	            if (firstName.equalsIgnoreCase(existing.getFirstName())
354	                && lastName.equalsIgnoreCase(existing.getLastName())) {
355	                count++;
356	            }
357	        }
358	        return count;
359	    }
360	
361	    /**
362	     * Counts the members of the household the new owner will belong to, as it stands after this
363	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
364	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
365	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
366	     * stored on the owner as its {@code householdMemberCount}.
367	     */
368	    private int countHouseholdMembers(String householdId) {
369	        int count = 1;
370	        for (Owner existing : this.clinicService.findAllOwners()) {
371	            if (householdId.equals(existing.getHouseholdId())) {
372	                count++;
373	            }
374	        }
375	        return count;
376	    }
377	
378	    /**
379	     * The membership level ceiling assigned on create; level 4 is reserved for tenure and so is
380	     * never reached here.
381	     */
382	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
383	
384	    /**
385	     * Computes the numeric {@code membershipLevel} for a newly created owner. It starts at 1,
386	     * gains 1 when an email is present, gains 1 when the owner's {@code namesakeCount} is 0, and
387	     * is capped at {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure). Evaluated after
388	     * the owner's email and namesakeCount have been set.
389	     */
390	    private static int membershipLevelFor(Owner owner) {
391	        int level = 1;
392	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
393	            level++;
394	        }
395	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
396	            level++;
397	        }
398	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
399	    }
400	
401	    /**
402	     * The maximum number of owners any single city may contain. A create whose city already
403	     * holds this many owners is rejected.
404	     */
405	    private static final int CITY_CAPACITY = 50;
406	
407	    /**
408	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
409	     * compared case-insensitively - the same way the city is matched when building the
410	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
411	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
412	     * translates to a 409.
413	     */
414	    private void rejectCityAtCapacity(String city) {
415	        int count = 0;
416	        for (Owner existing : this.clinicService.findAllOwners()) {
417	            if (city.equalsIgnoreCase(existing.getCity())) {
418	                count++;
419	            }
420	        }
421	        if (count >= CITY_CAPACITY) {
422	            throw new CityAtCapacityException(city);
423	        }
424	    }
425	
426	    /**
427	     * The maximum number of owners that may be created on any single day (by
428	     * {@code registrationDate}). A create attempted once this many owners already carry the
429	     * current day's registration date is rejected.
430	     */
431	    private static final int DAILY_OWNER_LIMIT = 100;
432	
433	    /**
434	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
435	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
436	     * The count reflects the state prior to this create. When the limit is reached the create is
437	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
438	     * to a 429 Too Many Requests.
439	     */
440	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
441	        int count = 0;
442	        for (Owner existing : this.clinicService.findAllOwners()) {
443	            if (registrationDate.equals(existing.getRegistrationDate())) {
444	                count++;
445	            }
446	        }
447	        if (count >= DAILY_OWNER_LIMIT) {
448	            throw new DailyOwnerLimitExceededException();
449	        }
450	    }
451	
452	    /**
453	     * The number of owners that must already carry a given {@code registrationDate} before a
454	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
455	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
456	     */
457	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
458	
459	    /**
460	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
461	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
462	     * have already been created for that date, otherwise false. The count reflects the state prior
463	     * to this create, matching how the daily-limit rule accumulates.
464	     */
465	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
466	        int count = 0;
467	        for (Owner existing : this.clinicService.findAllOwners()) {
468	            if (registrationDate.equals(existing.getRegistrationDate())) {
469	                count++;
470	            }
471	        }
472	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
473	    }
474	
475	    /**
476	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is
477	     * advanced to the following Monday; a weekday is returned unchanged. This is applied to the
478	     * effective registration date - whether supplied in the request or defaulted to the server
479	     * date - so the stored {@code registrationDate}, and everything derived from it, always falls
480	     * on a business day.
481	     */
482	    private static LocalDate toBusinessDay(LocalDate date) {
483	        return switch (date.getDayOfWeek()) {
484	            case SATURDAY -> date.plusDays(2);
485	            case SUNDAY -> date.plusDays(1);
486	            default -> date;
487	        };
488	    }
489	
490	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
491	    @Override
492	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
493	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
494	        rejectMissingOrBlankFields(ownerFieldsDto, normalizedAddress);
495	        rejectDuplicateHousehold(ownerFieldsDto, normalizedAddress);
496	        rejectCityAtCapacity(ownerFieldsDto.getCity());
497	        HttpHeaders headers = new HttpHeaders();
498	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
499	        owner.setAddress(normalizedAddress);
500	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
501	        rejectDuplicateTelephone(normalizedTelephone);
502	        owner.setTelephone(normalizedTelephone);
503	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
504	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
505	        LocalDate registrationDate = toBusinessDay(effectiveDate);
506	        rejectDailyOwnerLimit(registrationDate);
507	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
508	        owner.setRegistrationDate(registrationDate);
509	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
510	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
511	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getAddress()));
512	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
513	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
514	        owner.setMembershipLevel(membershipLevelFor(owner));
515	        this.clinicService.saveOwner(owner);
516	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
517	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
518	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
519	        headers.setLocation(UriComponentsBuilder.newInstance()
520	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
521	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
522	    }
523	
524	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
525	    @Override
526	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
527	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
528	        if (currentOwner == null) {
529	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
530	        }
531	        currentOwner.setAddress(ownerFieldsDto.getAddress());
532	        currentOwner.setCity(ownerFieldsDto.getCity());
533	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
534	        currentOwner.setLastName(ownerFieldsDto.getLastName());
535	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
536	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
537	        this.clinicService.saveOwner(currentOwner);
538	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
539	    }
540	
541	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
542	    @Transactional
543	    @Override
544	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
545	        Owner owner = this.clinicService.findOwnerById(ownerId);
546	        if (owner == null) {
547	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
548	        }
549	        this.clinicService.deleteOwner(owner);
550	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
551	    }
552	
553	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
554	    @Override
555	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
556	        Owner owner = this.clinicService.findOwnerById(ownerId);
557	        if (owner == null) {
558	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
559	        }
560	        HttpHeaders headers = new HttpHeaders();
561	        Pet pet = petMapper.toPet(petFieldsDto);
562	        owner.setId(ownerId);
563	        pet.setOwner(owner);
564	        pet.getType().setName(null);
565	        this.clinicService.savePet(pet);
566	        PetDto petDto = petMapper.toPetDto(pet);
567	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
568	            .buildAndExpand(pet.getId()).toUri());
569	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
570	    }
571	
572	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
573	    @Override
574	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
575	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
576	        if (currentOwner != null) {
577	            Pet currentPet = this.clinicService.findPetById(petId);
578	            if (currentPet != null) {
579	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
580	                currentPet.setName(petFieldsDto.getName());
581	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
582	                this.clinicService.savePet(currentPet);
583	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
584	            }
585	        }
586	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
587	    }
588	
589	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
590	    @Override
591	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
592	        HttpHeaders headers = new HttpHeaders();
593	        Visit visit = visitMapper.toVisit(visitFieldsDto);
594	        Pet pet = new Pet();
595	        pet.setId(petId);
596	        visit.setPet(pet);
597	        this.clinicService.saveVisit(visit);
598	        VisitDto visitDto = visitMapper.toVisitDto(visit);
599	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
600	            .buildAndExpand(visit.getId()).toUri());
601	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
602	    }
603	
604	
605	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
606	    @Override
607	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
608	        Owner owner = this.clinicService.findOwnerById(ownerId);
609	        if (owner != null) {
610	            Pet pet = owner.getPet(petId);
611	            if (pet != null) {
612	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
613	            }
614	        }
615	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
616	    }
617	}
